# Exact Laurent polynomials in tau and E = e^s, stored as {(i, k): coeff} for tau^i * E^k.
# d/ds of E^k equals k*E^k, so ds() is exact.

def clean(d):
    return {k: v for k, v in d.items() if v != 0}

def add(a, b):
    r = dict(a)
    for k, v in b.items():
        r[k] = r.get(k, 0) + v
    return clean(r)

def neg(a):
    return {k: -v for k, v in a.items()}

def sub(a, b):
    return add(a, neg(b))

def mul(a, b):
    r = {}
    for (i1, k1), v1 in a.items():
        for (i2, k2), v2 in b.items():
            key = (i1 + i2, k1 + k2)
            r[key] = r.get(key, 0) + v1 * v2
    return clean(r)

def ds(a):
    return clean({k: v * k[1] for k, v in a.items()})

def at_s0(a):
    # Evaluate at s = 0 (E = 1); returns {tau_power: coeff}
    r = {}
    for (i, _), v in a.items():
        r[i] = r.get(i, 0) + v
    return clean(r)

def m(c, i, k):
    return {(i, k): Fr(c)}

