categories = {
    "opinion", "size", "age", "shape",
    "color", "origin", "material", "purpose",
}
observed_sequences = [
    ("opinion", "color"),                 # e.g. silly violet
    ("size", "shape"),                   # e.g. little square
    ("material", "origin"),              # e.g. plastic egyptian
    ("origin", "age", "color"),          # turkish old green
    ("age", "purpose"),                  # old-fashioned typing
    ("material", "purpose", "opinion"),  # cardboard typing lovely
}

edges = set()
for sequence in observed_sequences:
    for i in range(len(sequence)):
        for j in range(i + 1, len(sequence)):
            edges.add((sequence[i], sequence[j]))

# Exhaustively enumerate all total category orders consistent with the
# observed constraints.
extensions = []
for order in itertools.permutations(categories):
    position = {category: i for i, category in enumerate(order)}
    if all(position[a] < position[b] for a, b in edges):
        extensions.append(position)

options = {
    "A": ("shape", "size", "age", "purpose", "opinion", "color"),
    "B": ("material", "origin", "age", "purpose", "opinion", "color",
          "size", "shape"),
    "C": ("shape", "age", "purpose", "opinion", "color", "origin",
          "material"),
    "D": ("age", "purpose", "opinion", "color", "size", "shape"),
    "E": ("material", "origin", "age", "purpose", "opinion", "color"),
    "F": ("material", "origin", "age", "purpose", "opinion", "color",
          "size"),
    "G": ("size", "shape", "age", "purpose", "opinion", "color"),
    "H": ("origin", "age", "purpose", "opinion", "color", "size", "shape"),
    "I": ("material", "origin", "age", "purpose", "opinion", "color",
          "shape"),
    "J": ("shape", "size", "age", "purpose", "opinion", "color", "origin"),
}

